// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e30);
        vm.deal(address(this), amount);
        (bool ok1, ) = address(c).call{value: amount}("");
        assertTrue(ok1);

        vm.prank(c.owner());
        c.withdrawAll();

        vm.deal(address(this), amount);
        (bool ok2, ) = address(c).call{value: amount}("");
        assertTrue(ok2);

        assertTrue(address(c).balance == amount);
    }
}
